"use strict";(globalThis.webpackChunkmy_website||=[]).push([[66157],{37392(e){e.exports=JSON.parse('{"slug":"djed","title":"Djed","short":"A crypto-backed, overcollateralized stablecoin protocol on Cardano whose US-dollar peg is maintained algorithmically against an ada reserve (with SHEN as the reserve coin), rather than by fiat reserves.","category":"tokens","aliases":[],"mentalModel":null,"related":["stablecoin","usdm"],"sources":[],"link":null,"level":"intermediate","body":"Djed maintains its US-dollar peg by mathematically constraining how much it can be minted relative to the ada in its reserve. While the reserve stays overcollateralized within roughly a 400-800% reserve ratio the protocol allows minting; if the ratio would drop below the 400% minimum, new DJED minting pauses to protect existing holders."}')}}]);